import { Controller } from '@nestjs/common';

// 이 기능은 화면만 만든다.
// GET/POST/PUT /payroll-codes API는 먼저 하는 작업에서 한 번만 만든다.
@Controller('api/v1')
export class FnSfr02005Controller {}

