import { useState } from 'react';
import { call, useData, Badge, Filters, Band, DataTable, Pager, Drawer, Form, Field, TextInput, Select, Tiles } from '../kit';
import type { PageProps, Row, Page } from '../kit';

const CODE_TYPES = ['근로소득', '퇴직소득', '소득공제', '농특세', '지방소득세', '사회보험 정산', '학자금 상환'];
const TYPE_OPTIONS: [string, string][] = CODE_TYPES.map((t) => [t, t]);
const USE_OPTIONS: [string, string][] = [['사용', '사용'], ['미사용', '미사용']];
const YN_OPTIONS: [string, string][] = [['Y', '대상'], ['N', '대상 아님']];
const SIZE = 20;

interface Editing {
  row?: Row;
}

function CodeForm({ role, notify, row, onDone }: { role: string; notify: (text: string) => void; row?: Row; onDone: () => void }) {
  const isEdit = row !== undefined;
  const [codeType, setCodeType] = useState(isEdit ? String(row.codeType ?? '') : '');
  const [code, setCode] = useState(isEdit ? String(row.code ?? '') : '');
  const [codeName, setCodeName] = useState(isEdit ? String(row.codeName ?? '') : '');
  const [sumYn, setSumYn] = useState(
    isEdit && row.socialInsuranceSumYn !== null && row.socialInsuranceSumYn !== undefined
      ? (row.socialInsuranceSumYn ? 'Y' : 'N')
      : '',
  );
  const [useStatus, setUseStatus] = useState(isEdit ? String(row.useStatus ?? '사용') : '사용');
  const [remark, setRemark] = useState(isEdit ? String(row.remark ?? '') : '');

  const showSum = codeType === '사회보험 정산';

  async function submit() {
    if (!isEdit && !codeType) throw new Error('코드 구분을 선택해 주세요.');
    if (!isEdit && !code.trim()) throw new Error('코드를 입력해 주세요.');
    if (!codeName.trim()) throw new Error('코드명을 입력해 주세요.');
    if (!useStatus) throw new Error('사용 여부를 선택해 주세요.');
    const body: Row = {
      codeName: codeName.trim(),
      useStatus,
      remark: remark,
    };
    if (showSum && sumYn) body.socialInsuranceSumYn = sumYn === 'Y';
    if (isEdit) {
      await call('PUT', '/payroll-codes/' + String(row.payrollCodeId), role, body);
      notify('급여 기초코드를 수정했습니다.');
    } else {
      body.codeType = codeType;
      body.code = code.trim();
      await call('POST', '/payroll-codes', role, body);
      notify('급여 기초코드를 등록했습니다.');
    }
    onDone();
  }

  return (
    <Form onSubmit={submit} submit={isEdit ? '수정' : '등록'}>
      <Field label='코드 구분' required>
        {isEdit ? (
          <span>{codeType}</span>
        ) : (
          <Select value={codeType} onChange={setCodeType} options={TYPE_OPTIONS} />
        )}
      </Field>
      <Field label='코드' required>
        {isEdit ? (
          <span>{code}</span>
        ) : (
          <TextInput value={code} onChange={setCode} />
        )}
      </Field>
      <Field label='코드명' required>
        <TextInput value={codeName} onChange={setCodeName} />
      </Field>
      {showSum && (
        <Field label='사회보험 합산 대상 여부'>
          <Select value={sumYn} onChange={setSumYn} options={YN_OPTIONS} />
        </Field>
      )}
      <Field label='사용 여부' required hint='미사용 코드는 이후 급여·정산 처리에서 선택할 수 없습니다.'>
        <Select value={useStatus} onChange={setUseStatus} options={USE_OPTIONS} />
      </Field>
      <Field label='비고' wide>
        <TextInput value={remark} onChange={setRemark} multiline />
      </Field>
    </Form>
  );
}

export default function FnSfr02005Page({ role, notify }: PageProps) {
  const [codeType, setCodeType] = useState('');
  const [applied, setApplied] = useState('');
  const [page, setPage] = useState(0);
  const [editing, setEditing] = useState<Editing | null>(null);

  const { data, error, loading, reload } = useData<Page>(
    () => call<Page>('GET', '/payroll-codes', role, undefined, { codeType: applied, page, size: SIZE }),
    [applied, page, role],
  );

  const items = data ? data.items : [];
  const usedCount = items.filter((r) => r.useStatus === '사용').length;
  const unusedCount = items.filter((r) => r.useStatus === '미사용').length;

  return (
    <div className='bento'>
      <section className='box span-8'>
        <h2>코드 목록</h2>
        <Filters
          onSearch={() => {
            setPage(0);
            setApplied(codeType);
          }}
          onReset={() => {
            setCodeType('');
            setApplied('');
            setPage(0);
          }}
        >
          <Field label='코드 구분'>
            <Select value={codeType} onChange={setCodeType} options={TYPE_OPTIONS} placeholder='전체' />
          </Field>
        </Filters>
        <Band total={data ? data.total : 0}>
          <button type='button' onClick={() => setEditing({})}>코드 등록</button>
        </Band>
        {error && <p>{error}</p>}
        {loading && <p>불러오는 중...</p>}
        <DataTable
          rows={items}
          empty='등록된 코드가 없습니다.'
          onRowClick={(r) => setEditing({ row: r })}
          columns={[
            { key: 'codeType', label: '코드 구분' },
            { key: 'code', label: '코드' },
            { key: 'codeName', label: '코드명' },
            {
              key: 'socialInsuranceSumYn',
              label: '사회보험 합산 대상 여부',
              render: (r) => (r.socialInsuranceSumYn === null || r.socialInsuranceSumYn === undefined ? '-' : r.socialInsuranceSumYn ? '대상' : '대상 아님'),
            },
            { key: 'useStatus', label: '사용 여부', render: (r) => <Badge value={r.useStatus} /> },
            { key: 'remark', label: '비고' },
          ]}
        />
        <Pager page={page} size={SIZE} total={data ? data.total : 0} onPage={setPage} />
      </section>
      <section className='box span-4'>
        <h2>현재 쪽 현황</h2>
        <Tiles
          items={[
            ['사용', usedCount],
            ['미사용', unusedCount],
          ]}
        />
      </section>
      {editing && (
        <Drawer title={editing.row ? '급여 기초코드 수정' : '급여 기초코드 등록'} onClose={() => setEditing(null)}>
          <CodeForm
            role={role}
            notify={notify}
            row={editing.row}
            onDone={() => {
              setEditing(null);
              reload();
            }}
          />
        </Drawer>
      )}
    </div>
  );
}
